import re

from robot.api import logger

from ta_egate_cmd_parser.egate_command_base import EgateCommandBase


class InfoFailure(Exception):
    """
    Exception class for info
    """
    pass


class Info(EgateCommandBase):
    """
    Parser for info command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(Info, self).__init__()
        self.command = 'info'
        self.params = params
        self.executed_phrase = r'.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return: parsed output
        """
        status, output = self.execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_with_default_params(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output

    def _build_command(self):
        """
        Build sim_debug_log command.
        :return: None
        """
        for param, value in self.params.items():
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_with_default_params(self, cmd_output):
        """
        Parse info command output.
        :param cmd_output: output received from execution of info command

        e.g.:

        EGATE> info

        LTE WTS (SimMode) Management Gate (WTS_1088058.2_4.0.7402)
        Copyright Nokia 2019
        Compiled on Jun 24 2019, 13:32:33

        Telnet Port: 20000
        Work Directory: /opt/iphy/WTS_7402
        User: 1000 (ute)
        Process ID: 9182
        Inactivity timeout: 168 hours


        EGATE>

        :return:

        """
        if re.findall(r'Error:.*', str(cmd_output)):
            raise InfoFailure(re.findall(r'Error:.*', str(cmd_output))[0])
        else:
            output = '\n'.join([line for line in cmd_output.splitlines() if line])
            return output
